  BridgeStats sameDay=new BridgeStats(at("2026-11-13T00:00:00Z"));sameDay.record("a",ServerMode.Mode.SHORT,at("2026-11-13T08:01:00Z"),true,4,1);sameDay.record("a",ServerMode.Mode.SHORT,at("2026-11-13T08:02:00Z"),true,5,1);BridgeStats.View detail=sameDay.view("",null,BridgeStats.Period.THIS_WEEK,now,zone);check(detail.points.size()==2&&detail.points.get(0).totals.average()==4&&detail.points.get(1).totals.average()==5,"Same-day weekly chart collapsed all runs into one daily point");
  Path file=Files.createTempDirectory("bridge-stats-").resolve("stats.properties");stats.historicalIds.add("00000000-0000-0000-0000-000000000001");stats.write(file);BridgeStats reloaded=BridgeStats.read(file,0);check(reloaded.view("",null,BridgeStats.Period.ALL_TIME,now,zone).totals.attempts==6&&reloaded.historicalIds.size()==1,"Counts or resumable historical import did not survive restart");reloaded.imported=true;reloaded.historicalIds.clear();reloaded.write(file);check(BridgeStats.read(file,0).imported,"Import completion was not persisted");
  Properties legacy=new Properties();legacy.setProperty("version","1");legacy.setProperty("since",Long.toString(at("2026-11-13T00:00:00Z")));legacy.setProperty("bucket."+(at("2026-11-13T08:00:00Z")/3600000)+".YQ.NORMAL","2,1,4,16,4,4,2");try(java.io.OutputStream out=Files.newOutputStream(file)){legacy.store(out,"legacy");}BridgeStats migrated=BridgeStats.read(file,0);BridgeStats.View old=migrated.view("a",null,BridgeStats.Period.TODAY,now,zone);check(old.totals.attempts==2&&old.points.get(0).label.equals("09:00"),"Legacy hourly totals were lost or moved to the wrong date");migrated.write(file);check(BridgeStats.read(file,0).view("a",null,BridgeStats.Period.TODAY,now,zone).totals.attempts==2,"Migrated statistics lost on restart");
  check(Double.isNaN(stats.view("missing",null,BridgeStats.Period.TODAY,now,zone).totals.average()),"Empty selection invented an average");try{stats.record("bad",ServerMode.Mode.NORMAL,1,true,Double.NaN,0);throw new AssertionError("NaN accepted");}catch(IllegalArgumentException good){}Properties invalid=new Properties();invalid.setProperty("version","1");invalid.setProperty("since","0");invalid.setProperty("bucket.1.YQ.NORMAL","1,2,1,1,1,1,1");try(java.io.OutputStream out=Files.newOutputStream(file)){invalid.store(out,"invalid");}try{BridgeStats.read(file,0);throw new AssertionError("Invalid success counts accepted");}catch(java.io.IOException good){}
  System.out.println("PASS: server/mode/date filters, weighted success means, rates, local-midnight/hour/week charts, persistence, resumable history and corrupt-data rejection");
